/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,12],[12,40],[40,64],[64,80]]);
  for (var i = 0; i < 8; i++) v['r'+i] = p >= 14 + i * 2.8 ? out : 0;
  var b = lin([[44,0],[56,1]]);
  var A1 = 4.54 + (3.70 - 4.54) * b, A2 = 2.34 + (3.70 - 2.34) * b, A3 = 4.20 + (3.70 - 4.20) * b;
  var sh = p >= 38 ? 1 : 0;
  v.b1 = (sh * A1 / 5 * 100).toFixed(1) + '%'; v.b2 = (sh * A2 / 5 * 100).toFixed(1) + '%'; v.b3 = (sh * A3 / 5 * 100).toFixed(1) + '%';
  v.tb1 = sh ? A1.toFixed(2) + ' kW' : ''; v.tb2 = sh ? A2.toFixed(2) + ' kW' : ''; v.tb3 = sh ? A3.toFixed(2) + ' kW' : '';
  v.tt = p >= 38 ? out : 0.25 * out;
  var imb = Math.round(48 - 46 * b); v.im = imb + '%'; v.ic = imb > 10 ? '#C0392B' : '#1E7F4F';
  v.fin = (p >= 70 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
